using Microsoft.ML;
using Microsoft.ML.Data;
using Microsoft.Extensions.ML;

var builder = WebApplication.CreateBuilder(args);

// Train the model at startup
var mlContext = new MLContext(seed: 42);
var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
var rawData = mlContext.Data.LoadFromTextFile<RawChurnInput>(dataPath, hasHeader: true, separatorChar: ',');

// Map "Yes"/"No" string to a bool Label column
var labelKeys = new[] { new LabelMapping { Churned = "Yes", Label = true },
                        new LabelMapping { Churned = "No",  Label = false } };
var labelLookup = mlContext.Data.LoadFromEnumerable(labelKeys);

var pipeline = mlContext.Transforms.Conversion.MapValue("Label", labelLookup,
        labelLookup.Schema["Churned"], labelLookup.Schema["Label"],
        inputColumnName: nameof(RawChurnInput.Churned))
    .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(RawChurnInput.Region)))
    .Append(mlContext.Transforms.Concatenate("Features",
        nameof(RawChurnInput.Age), nameof(RawChurnInput.Income),
        "RegionEncoded", nameof(RawChurnInput.PurchaseHistory)))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
        labelColumnName: "Label", featureColumnName: "Features"));

var split = mlContext.Data.TrainTestSplit(rawData, testFraction: 0.2);
var model = pipeline.Fit(split.TrainSet);

// Log evaluation metrics
var predictions = model.Transform(split.TestSet);
var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
Console.WriteLine($"Model trained — AUC: {metrics.AreaUnderRocCurve:F4}, Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");

// Save model and register the thread-safe prediction engine pool
var modelPath = Path.Combine(AppContext.BaseDirectory, "churn-model.zip");
mlContext.Model.Save(model, rawData.Schema, modelPath);

builder.Services.AddPredictionEnginePool<RawChurnInput, ChurnOutput>()
    .FromFile(modelPath);

var app = builder.Build();

app.MapGet("/", () => "Churn Predictor API — POST to /predict");

app.MapPost("/predict", (PredictionEnginePool<RawChurnInput, ChurnOutput> pool, ChurnRequest request) =>
{
    var input = new RawChurnInput
    {
        Age = request.Age,
        Income = request.Income,
        Region = request.Region,
        PurchaseHistory = request.PurchaseHistory,
    };
    var prediction = pool.Predict(input);
    return Results.Ok(new
    {
        WillChurn = prediction.PredictedLabel,
        Probability = prediction.Probability,
    });
});

app.Run();

// Input schema matching the CSV columns
public class RawChurnInput
{
    [LoadColumn(0)]
    public float Age { get; set; }

    [LoadColumn(1)]
    public float Income { get; set; }

    [LoadColumn(2)]
    public string Region { get; set; } = string.Empty;

    [LoadColumn(3)]
    public float PurchaseHistory { get; set; }

